function validate(input) {
  const [{ Books = [], Orders = [] }] = input;
  const books = new Set(), orders = new Set();
  for (const [id, , from] of Books) {
    if (id === null) return 'Every book needs a book_id.';
    if (books.has(id)) return `book_id ${id} appears twice in Books.`;
    if (from === null) return 'Every book needs an available_from date.';
    books.add(id);
  }
  for (const [id, bookId, quantity, date] of Orders) {
    if (id === null) return 'Every order needs an order_id.';
    if (orders.has(id)) return `order_id ${id} appears twice in Orders.`;
    orders.add(id);
    if (!books.has(bookId)) return `Order ${id} names book_id ${bookId}, which is not in Books.`;
    if (quantity === null || quantity < 1) return `Order ${id} needs a quantity of at least 1.`;
    if (date === null || date > '2019-06-23') return `Order ${id} must be dispatched on or before 2019-06-23.`;
  }
  return null;
}

