function generate(rand, size) {
  const titles = ['Kalila And Demna', '28 Letters', 'The Hobbit', '13 Reasons Why', 'The Hunger Games', 'Dune', 'Emma', 'Dune'];
  const releases = ['2008-09-21', '2010-01-01', '2015-03-01', '2018-07-01', '2019-05-22', '2019-05-23', '2019-06-01', '2019-06-10'];
  const dispatches = ['2017-12-01', '2018-06-22', '2018-06-23', '2018-07-26', '2018-11-05', '2019-02-14', '2019-06-05', '2019-06-23'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const bookCount = small ? Math.floor(rand() * 7) : 1000;
  const orderCount = bookCount === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  const Books = [], Orders = [];
  for (let id = 1; id <= bookCount; id++) Books.push([id, pick(titles), pick(releases)]);
  // Quantities cluster around the threshold of 10 so books land on both sides of it, and exactly on it.
  const quantities = small ? [1, 2, 3, 4, 5, 6, 9, 10] : [1, 2, 3, 4, 5, 6];
  for (let id = 1; id <= orderCount; id++) {
    const bookId = small && id > 1 && rand() < 0.3 ? Orders[id - 2][1] : 1 + Math.floor(rand() * bookCount);
    Orders.push([id, bookId, pick(quantities), pick(dispatches)]);
  }
  return [{ Books, Orders }];
}
